import net.runelite.api.Client;
import net.runelite.api.Skill;

/**
 * Era gates. {@link #satisfiedBy(Client)} is evaluated against live stats so the
 * plugin can advance the deck by itself the moment the account crosses a gate.
 */
public enum Era
{
	WAKING("I", "The Waking", "WAK", 0, 0, "Obor"),
	WANDERING("II", "The Wandering", "WAN", 40, 500, "Sarachnis"),
	ASCENT("III", "The Ascent", "ASC", 55, 900, "Abyssal Sire"),
	CRUCIBLE("IV", "The Crucible", "CRU", 70, 1400, "Nex"),
	RECKONING("V", "The Reckoning", "REC", 85, 1750, "The Inferno");

	private final String numeral;
	private final String title;
	private final String code;
	private final int baseCombat;
	private final int totalLevel;
	private final String herald;

	Era(String numeral, String title, String code, int baseCombat, int totalLevel, String herald)
	{
		this.numeral = numeral;
		this.title = title;
		this.code = code;
		this.baseCombat = baseCombat;
		this.totalLevel = totalLevel;
		this.herald = herald;
	}

	public String getNumeral()
	{
		return numeral;
	}

	public String getTitle()
	{
		return title;
	}

	public String getCode()
	{
		return code;
	}

	public int getBaseCombat()
	{
		return baseCombat;
	}

	public int getTotalLevel()
	{
		return totalLevel;
	}

	public String getHerald()
	{
		return herald;
	}

	/** Long Vows only exist from Era III, where the account can carry them. */
	public boolean allowsLongVows()
	{
		return ordinal() >= ASCENT.ordinal();
	}

	public Era next()
	{
		return this == RECKONING ? RECKONING : values()[ordinal() + 1];
	}

	/**
	 * A gate is met when the lowest of the four melee/ranged/magic base levels
	 * clears {@link #baseCombat} and total level clears {@link #totalLevel}.
	 */
	public boolean satisfiedBy(Client client)
	{
		if (client == null)
		{
			return false;
		}

		int lowestBase = Math.min(
			Math.min(client.getRealSkillLevel(Skill.ATTACK), client.getRealSkillLevel(Skill.STRENGTH)),
			Math.min(client.getRealSkillLevel(Skill.DEFENCE),
				Math.min(client.getRealSkillLevel(Skill.RANGED), client.getRealSkillLevel(Skill.MAGIC))));

		return lowestBase >= baseCombat && client.getTotalLevel() >= totalLevel;
	}

	/** The highest Era whose gate the account currently satisfies. */
	public static Era highestSatisfied(Client client)
	{
		Era best = WAKING;
		for (Era era : values())
		{
			if (era.satisfiedBy(client))
			{
				best = era;
			}
		}
		return best;
	}
}

package com.oathfall.model;

/**
 * How {@code ObjectiveTracker} measures a Vow's progress. MANUAL means the
 * objective has no reliable client-side signal and the player ticks it off
 * themselves — the plugin never guesses at those.
 */
public enum GoalType
{
	/** Reach a level in a named skill. target = skill name, amount = level. */
	SKILL_LEVEL,
	/** Reach a total level. amount = total. */
	TOTAL_LEVEL,
	/** Kill count deltas parsed from the game's own kill-count messages. */
	KILL_COUNT,
	/** Completed clue scrolls of a tier. target = tier name, amount = count. */
	CLUE_COUNT,
	/** A quest reaching FINISHED. target = Quest enum name. */
	QUEST,
	/** An item appearing in inventory, equipment or bank. target = item name. */
	ITEM,
	/** Player-confirmed only. */
	MANUAL
}

package com.oathfall.model;

import java.util.ArrayList;
import java.util.List;

/**
 * The whole persisted run. Serialised to the RuneLite config store as JSON and
 * served verbatim to the companion tracker, so field names here are the public
 * shape of the relay API.
 */
public class Ledger
{
	// --- covenant state -----------------------------------------------------
	public Era era = Era.WAKING;
	public int doom = 0;
	public int grace = 0;
	public int streak = 0;               // consecutive Kept Oaths
	public int tempers = 0;              // banked redraws
	public boolean hollowed = false;
	public boolean hollowSpent = false;  // you may Hollow once
	public boolean vigilUsedThisEra = false;
	/** Scars absolved so far; drives the escalating Absolve cost. Persisted. */
	public int absolved = 0;

	public List<Scar> scars = new ArrayList<>();
	public List<String> keptOaths = new ArrayList<>();
	public List<String> consecrations = new ArrayList<>();

	// --- the table ----------------------------------------------------------
	/** Three Vow ids: two from the deck, the third is the Audience's Card. */
	public List<String> hand = new ArrayList<>();

	// --- the sworn Vow ------------------------------------------------------
	public String activeVowId = null;
	public boolean activeIsAudienceCard = false;
	public long activeSwornAt = 0L;
	public int activeProgress = 0;
	public int activeBaseline = 0;       // counter value at the moment of swearing
	public boolean activeBroken = false;
	public String activeBreakReason = null;

	/** Doom steps that have already been answered, so a Herald fires once each. */
	public List<Integer> heraldsAnswered = new ArrayList<>();

	public int graceCap()
	{
		return scars.contains(Scar.CRACKED_LEDGER) ? 8 : 10;
	}

	/** Absolve costs 6, and one more for every Scar already absolved. */
	public int absolveCost()
	{
		return 6 + absolved;
	}

	public boolean heraldDue()
	{
		int step = effectiveDoom();
		return (step == 3 || step == 6 || step == 9) && !heraldsAnswered.contains(step);
	}

	/** Record that the Herald standing at the current step has been answered. */
	public void markHeraldAnswered()
	{
		int step = effectiveDoom();
		if (!heraldsAnswered.contains(step))
		{
			heraldsAnswered.add(step);
		}
	}

	/** The Marked Scar pulls the next Herald one step closer. */
	public int effectiveDoom()
	{
		return scars.contains(Scar.MARKED) ? Math.min(10, doom + 1) : doom;
	}

	public boolean hasActiveVow()
	{
		return activeVowId != null;
	}

	public void addGrace(int amount)
	{
		grace = Math.min(graceCap(), grace + amount);
	}

	public void clearActive()
	{
		activeVowId = null;
		activeIsAudienceCard = false;
		activeSwornAt = 0L;
		activeProgress = 0;
		activeBaseline = 0;
		activeBroken = false;
		activeBreakReason = null;
	}
}

