/** One card in an Era deck. Immutable; live progress lives on the Ledger. */
public class Vow
{
	private final String id;
	private final Era era;
	private final int index;
	private final String objective;
	private final Binding binding;
	private final Length length;
	private final GoalType goalType;
	private final String goalTarget;
	private final int goalAmount;

	public Vow(Era era, int index, String objective, Binding binding, Length length,
			   GoalType goalType, String goalTarget, int goalAmount)
	{
		this.era = era;
		this.index = index;
		this.id = String.format("%s-%02d", era.getCode(), index + 1);
		this.objective = objective;
		this.binding = binding;
		this.length = length;
		this.goalType = goalType;
		this.goalTarget = goalTarget;
		this.goalAmount = goalAmount;
	}

	public String getId()
	{
		return id;
	}

	public Era getEra()
	{
		return era;
	}

	public int getIndex()
	{
		return index;
	}

	public String getObjective()
	{
		return objective;
	}

	public Binding getBinding()
	{
		return binding;
	}

	public Length getLength()
	{
		return length;
	}

	public GoalType getGoalType()
	{
		return goalType;
	}

	public String getGoalTarget()
	{
		return goalTarget;
	}

	public int getGoalAmount()
	{
		return goalAmount;
	}

	public boolean isAutoTracked()
	{
		return goalType != GoalType.MANUAL;
	}

	/** Grace paid on a Kept Oath. The Audience's Card is worth one more. */
	public int graceValue(boolean audienceCard)
	{
		return length.getGrace() + (audienceCard ? 1 : 0);
	}

	@Override
	public String toString()
	{
		return id + " " + objective + " [" + binding.getTitle() + "]";
	}
}

package com.oathfall.relay;

import com.sun.net.httpserver.HttpExchange;
import com.sun.net.httpserver.HttpServer;
import lombok.extern.slf4j.Slf4j;

import java.io.IOException;
import java.io.InputStream;
import java.io.OutputStream;
import java.net.InetAddress;
import java.net.InetSocketAddress;
import java.net.URI;
import java.nio.charset.StandardCharsets;
import java.security.SecureRandom;
import java.util.ArrayList;
import java.util.Base64;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.concurrent.CopyOnWriteArrayList;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;

/**
 * A loopback-only HTTP relay that serves the Oathfall companion tracker and a
 * live ledger feed.
 *
 * Deliberate constraints, because this is what Plugin Hub review will ask about:
 *   - binds to 127.0.0.1, so nothing on the network can reach it;
 *   - every request must carry a token minted fresh each session;
 *   - it is off by default and never contacts anything outbound.
 */
@Slf4j
public class RelayServer
{
	/** Actions the tracker page can ask the plugin to perform. */
	public interface Handler
	{
		String ledgerJson();

		void deal();

		void swear(String vowId);

		void settleKept();

		void settleBroken(String reason);

		void spend(String rite, String argument);
	}

	private final Handler handler;
	private final String token;
	private final List<HttpExchange> streams = new CopyOnWriteArrayList<>();

	private HttpServer server;
	private ExecutorService executor;
	private int port;

	public RelayServer(Handler handler)
	{
		this.handler = handler;
		byte[] raw = new byte[18];
		new SecureRandom().nextBytes(raw);
		this.token = Base64.getUrlEncoder().withoutPadding().encodeToString(raw);
	}

	public void start(int port) throws IOException
	{
		stop();
		this.port = port;

		server = HttpServer.create(new InetSocketAddress(InetAddress.getByName("127.0.0.1"), port), 0);
		executor = Executors.newFixedThreadPool(2);
		server.setExecutor(executor);

		server.createContext("/", this::serveTracker);
		server.createContext("/api/ledger", this::serveLedger);
		server.createContext("/api/stream", this::serveStream);
		server.createContext("/api/action", this::serveAction);

		server.start();
		log.info("Oathfall relay listening on {}", url());
	}

	public void stop()
	{
		for (HttpExchange ex : streams)
		{
			try
			{
				ex.close();
			}
			catch (RuntimeException ignored)
			{
				// client already gone
			}
		}
		streams.clear();

		if (server != null)
		{
			server.stop(0);
			server = null;
		}

		// HttpServer.stop does not touch the executor, so toggling the relay would
		// otherwise leak its threads every time it was switched back on.
		if (executor != null)
		{
			executor.shutdownNow();
			executor = null;
		}
	}

	public boolean isRunning()
	{
		return server != null;
	}

	/** The address to open in a browser, token included. */
	public String url()
	{
		return "http://127.0.0.1:" + port + "/?t=" + token;
	}

	/** Push the current ledger to every connected tracker page. */
	public void broadcast(String json)
	{
		byte[] payload = ("data: " + json.replace("\n", " ") + "\n\n").getBytes(StandardCharsets.UTF_8);

		for (HttpExchange ex : streams)
		{
			try
			{
				OutputStream out = ex.getResponseBody();
				out.write(payload);
				out.flush();
			}
			catch (IOException e)
			{
				streams.remove(ex);
				try
				{
					ex.close();
				}
				catch (RuntimeException ignored)
				{
					// nothing to do
				}
			}
		}
	}

	// ------------------------------------------------------------------ routes

	private void serveTracker(HttpExchange ex) throws IOException
	{
		if (!authorised(ex))
		{
			return;
		}

		byte[] page;
		try (InputStream in = getClass().getResourceAsStream("/com/oathfall/tracker.html"))
		{
			if (in == null)
			{
				send(ex, 500, "text/plain", "tracker.html missing from the plugin jar".getBytes(StandardCharsets.UTF_8));
				return;
			}
			page = readAll(in);
		}

		// The page needs the token to call back into the relay.
		String html = new String(page, StandardCharsets.UTF_8).replace("__OATHFALL_TOKEN__", token);
		send(ex, 200, "text/html; charset=utf-8", html.getBytes(StandardCharsets.UTF_8));
	}

	private void serveLedger(HttpExchange ex) throws IOException
	{
		if (!authorised(ex))
		{
			return;
		}
		send(ex, 200, "application/json; charset=utf-8", handler.ledgerJson().getBytes(StandardCharsets.UTF_8));
	}

	private void serveStream(HttpExchange ex) throws IOException
	{
		if (!authorised(ex))
		{
			return;
		}

		ex.getResponseHeaders().add("Content-Type", "text/event-stream; charset=utf-8");
		ex.getResponseHeaders().add("Cache-Control", "no-store");
		ex.getResponseHeaders().add("Connection", "keep-alive");
		ex.sendResponseHeaders(200, 0);

		streams.add(ex);

		OutputStream out = ex.getResponseBody();
		out.write(("data: " + handler.ledgerJson().replace("\n", " ") + "\n\n").getBytes(StandardCharsets.UTF_8));
		out.flush();
	}

	private void serveAction(HttpExchange ex) throws IOException
	{
		if (!authorised(ex))
		{
			return;
		}

		if (!"POST".equalsIgnoreCase(ex.getRequestMethod()))
		{
			send(ex, 405, "text/plain", "POST only".getBytes(StandardCharsets.UTF_8));
			return;
		}

		Map<String, String> q = query(ex.getRequestURI());
		String action = q.getOrDefault("do", "");
		String arg = q.getOrDefault("arg", "");

		try
		{
			switch (action)
			{
				case "deal":
					handler.deal();
					break;
				case "swear":
					handler.swear(arg);
					break;
				case "kept":
					handler.settleKept();
					break;
				case "broken":
					handler.settleBroken(arg.isEmpty() ? "Settled from the tracker" : arg);
					break;
				case "spend":
					handler.spend(arg, q.getOrDefault("arg2", ""));
					break;
				default:
					send(ex, 400, "text/plain", "unknown action".getBytes(StandardCharsets.UTF_8));
					return;
			}
		}
		catch (RuntimeException e)
		{
			log.warn("Oathfall relay action '{}' failed", action, e);
			send(ex, 500, "text/plain", "action failed".getBytes(StandardCharsets.UTF_8));
			return;
		}

		send(ex, 200, "application/json; charset=utf-8", handler.ledgerJson().getBytes(StandardCharsets.UTF_8));
	}

	// ------------------------------------------------------------------ plumbing

	private boolean authorised(HttpExchange ex) throws IOException
	{
		String supplied = query(ex.getRequestURI()).get("t");
		if (token.equals(supplied))
		{
			return true;
		}

		send(ex, 403, "text/plain", "Oathfall relay: bad or missing token".getBytes(StandardCharsets.UTF_8));
		return false;
	}

	private static Map<String, String> query(URI uri)
	{
		Map<String, String> out = new HashMap<>();
		String raw = uri.getRawQuery();
		if (raw == null || raw.isEmpty())
		{
			return out;
		}

		for (String pair : raw.split("&"))
		{
			int eq = pair.indexOf('=');
			if (eq <= 0)
			{
				continue;
			}
			out.put(decode(pair.substring(0, eq)), decode(pair.substring(eq + 1)));
		}
		return out;
	}

	private static String decode(String s)
	{
		try
		{
			return java.net.URLDecoder.decode(s, StandardCharsets.UTF_8.name());
		}
		catch (Exception e)
		{
			return s;
		}
	}

	private static void send(HttpExchange ex, int status, String contentType, byte[] body) throws IOException
	{
		ex.getResponseHeaders().add("Content-Type", contentType);
		ex.getResponseHeaders().add("Cache-Control", "no-store");
		ex.sendResponseHeaders(status, body.length);
		try (OutputStream out = ex.getResponseBody())
		{
			out.write(body);
		}
	}

	private static byte[] readAll(InputStream in) throws IOException
	{
		List<byte[]> chunks = new ArrayList<>();
		byte[] buf = new byte[8192];
		int total = 0, read;
		while ((read = in.read(buf)) > 0)
		{
			byte[] chunk = new byte[read];
			System.arraycopy(buf, 0, chunk, 0, read);
			chunks.add(chunk);
			total += read;
		}

		byte[] all = new byte[total];
		int at = 0;
		for (byte[] chunk : chunks)
		{
			System.arraycopy(chunk, 0, all, at, chunk.length);
			at += chunk.length;
		}
		return all;
	}
}

package com.oathfall.track;

import com.oathfall.model.Binding;
import net.runelite.api.Client;
import net.runelite.api.EquipmentInventorySlot;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.api.Prayer;
import net.runelite.api.gameval.InventoryID;
import net.runelite.api.gameval.VarPlayerID;

import javax.annotation.Nullable;
import java.util.Locale;

/**
 * Watches for observable Binding breaks.
 *
 * Every check is passive: it reads game state and menu options the player has
 * already clicked. Nothing here sends input to the client — the Plugin Hub
 * forbids gameplay automation, and so does Jagex.
 */
public class BindingMonitor
{
	private final Client client;

	public BindingMonitor(Client client)
	{
		this.client = client;
	}

	/**
	 * Per-tick state checks. Returns a human-readable break reason, or null.
	 */
	@Nullable
	public String checkTick(Binding binding)
	{
		switch (binding)
		{
			case SILENT:
				Prayer active = activePrayer();
				return active == null ? null : "Prayer used: " + pretty(active.name());

			case SUNLESS:
				return client.getVarpValue(VarPlayerID.OPTION_RUN) == 1 ? "Run energy enabled" : null;

			case BAREFOOT:
				String worn = firstWorn(EquipmentInventorySlot.BOOTS, EquipmentInventorySlot.GLOVES, EquipmentInventorySlot.CAPE);
				return worn == null ? null : "Equipped in a sealed slot: " + worn;

			case ONE_HANDED:
				String shield = firstWorn(EquipmentInventorySlot.SHIELD);
				return shield == null ? null : "Shield slot filled: " + shield;

			default:
				return null;
		}
	}

	/**
	 * Menu-click checks. {@code option} and {@code target} come straight from the
	 * MenuOptionClicked event.
	 */
	@Nullable
	public String checkMenuClick(Binding binding, String option, String target)
	{
		String opt = option == null ? "" : option.toLowerCase(Locale.ROOT);
		String tgt = target == null ? "" : target.toLowerCase(Locale.ROOT);

		switch (binding)
		{
			case STARVING:
				if (opt.equals("eat"))
				{
					return "Ate " + target;
				}
				// Drinking a brew or a stew still counts as food.
				if (opt.equals("drink") && (tgt.contains("brew") || tgt.contains("stew") || tgt.contains("wine")))
				{
					return "Drank " + target;
				}
				return null;

			case COLD_IRON:
				if (opt.equals("drink"))
				{
					return "Drank " + target;
				}
				return null;

			case GROUNDED:
				if (opt.contains("teleport") || tgt.contains("teleport") || opt.equals("rub") && tgt.contains("glory"))
				{
					return "Teleported: " + (target == null || target.isEmpty() ? option : target);
				}
				return null;

			default:
				return null;
		}
	}

	@Nullable
	private Prayer activePrayer()
	{
		for (Prayer prayer : Prayer.values())
		{
			try
			{
				if (client.getVarbitValue(prayer.getVarbit()) == 1)
				{
					return prayer;
				}
			}
			catch (RuntimeException ignored)
			{
				// Prayer enum gains entries across game updates; skip unknowns.
			}
		}
		return null;
	}

	@Nullable
	private String firstWorn(EquipmentInventorySlot... slots)
	{
		ItemContainer equipment = client.getItemContainer(InventoryID.WORN);
		if (equipment == null)
		{
			return null;
		}

		for (EquipmentInventorySlot slot : slots)
		{
			Item item = equipment.getItem(slot.getSlotIdx());
			if (item != null && item.getId() > 0)
			{
				return client.getItemDefinition(item.getId()).getName();
			}
		}
		return null;
	}

	private static String pretty(String enumName)
	{
		String s = enumName.toLowerCase(Locale.ROOT).replace('_', ' ');
		return Character.toUpperCase(s.charAt(0)) + s.substring(1);
	}
}

package com.oathfall.track;

import com.oathfall.model.GoalType;
import com.oathfall.model.Vow;
import net.runelite.api.Client;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.api.Quest;
import net.runelite.api.QuestState;
import net.runelite.api.Skill;
import net.runelite.api.gameval.InventoryID;

import java.util.Locale;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

/**
 * Measures how far along a sworn Vow is, from signals the client already
 * produces. Counting objectives are measured as a delta against the baseline
 * captured when the Vow was sworn, so previous progress never counts twice.
 */
public class ObjectiveTracker
{
	/** "Your Zulrah kill count is: 143." and the Barrows/raids variants. */
	private static final Pattern KILL_COUNT = Pattern.compile(
		"Your (?:completed )?(.+?) (?:kill )?count is: <col=[^>]+>([\\d,]+)</col>", Pattern.CASE_INSENSITIVE);

	/** "You have completed 42 medium Treasure Trails." */
	private static final Pattern CLUE_COUNT = Pattern.compile(
		"You have completed ([\\d,]+) (\\w+) Treasure Trails", Pattern.CASE_INSENSITIVE);

	private final Client client;

	public ObjectiveTracker(Client client)
	{
		this.client = client;
	}

	/**
	 * The absolute counter a Vow is measured against. Called once at swearing
	 * time for the baseline, then again whenever a relevant event fires.
	 */
	public int currentCounter(Vow vow)
	{
		switch (vow.getGoalType())
		{
			case SKILL_LEVEL:
				Skill skill = skill(vow.getGoalTarget());
				return skill == null ? 0 : client.getRealSkillLevel(skill);

			case TOTAL_LEVEL:
				return client.getTotalLevel();

			case QUEST:
				Quest quest = quest(vow.getGoalTarget());
				return quest != null && quest.getState(client) == QuestState.FINISHED ? 1 : 0;

			case ITEM:
				return countItem(vow.getGoalTarget());

			default:
				// KILL_COUNT and CLUE_COUNT arrive by chat message, not by polling.
				return 0;
		}
	}

	/**
	 * Level and total-level goals are absolute targets, not deltas — reaching 70
	 * Slayer means 70, regardless of where you started.
	 */
	public boolean isAbsolute(Vow vow)
	{
		GoalType type = vow.getGoalType();
		return type == GoalType.SKILL_LEVEL || type == GoalType.TOTAL_LEVEL || type == GoalType.QUEST;
	}

	/**
	 * Parse a chat message for a counter relevant to this Vow.
	 *
	 * @return the new absolute count, or -1 when the message is irrelevant.
	 */
	public int parseChat(Vow vow, String message)
	{
		String clean = message == null ? "" : message;

		if (vow.getGoalType() == GoalType.KILL_COUNT)
		{
			Matcher m = KILL_COUNT.matcher(clean);
			if (m.find() && m.group(1).equalsIgnoreCase(vow.getGoalTarget()))
			{
				return parseInt(m.group(2));
			}
		}

		if (vow.getGoalType() == GoalType.CLUE_COUNT)
		{
			Matcher m = CLUE_COUNT.matcher(clean);
			if (m.find() && m.group(2).equalsIgnoreCase(vow.getGoalTarget()))
			{
				return parseInt(m.group(1));
			}
		}

		return -1;
	}

	private int countItem(String name)
	{
		int total = 0;
		total += countIn(InventoryID.INV, name);
		total += countIn(InventoryID.WORN, name);
		total += countIn(InventoryID.BANK, name);
		return total;
	}

	private int countIn(int containerId, String name)
	{
		ItemContainer container = client.getItemContainer(containerId);
		if (container == null || name == null || name.isEmpty())
		{
			return 0;
		}

		int total = 0;
		for (Item item : container.getItems())
		{
			if (item == null || item.getId() <= 0)
			{
				continue;
			}
			String itemName = client.getItemDefinition(item.getId()).getName();
			if (itemName != null && itemName.equalsIgnoreCase(name))
			{
				total += Math.max(1, item.getQuantity());
			}
		}
		return total;
	}

	private static Skill skill(String name)
	{
		try
		{
			return Skill.valueOf(name.toUpperCase(Locale.ROOT));
		}
		catch (IllegalArgumentException e)
		{
			return null;
		}
	}

	private static Quest quest(String name)
	{
		try
		{
			return Quest.valueOf(name.toUpperCase(Locale.ROOT));
		}
		catch (IllegalArgumentException e)
		{
			return null;
		}
	}

	private static int parseInt(String raw)
	{
		try
		{
			return Integer.parseInt(raw.replace(",", ""));
		}
		catch (NumberFormatException e)
		{
			return -1;
		}
	}
}

package com.oathfall.ui;

import com.oathfall.OathfallConfig;
import com.oathfall.OathfallPlugin;
import com.oathfall.model.Ledger;
import com.oathfall.model.Vow;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPanel;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.components.LineComponent;
import net.runelite.client.ui.overlay.components.TitleComponent;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;

/** The sworn Vow, its Binding, and the Doom clock, over the game window. */
public class OathfallOverlay extends OverlayPanel
{
	private static final Color EMBER = new Color(0xED, 0xBB, 0x59);
	private static final Color DOOM = new Color(0xCB, 0x69, 0x7F);
	private static final Color INK = new Color(0xE9, 0xE5, 0xD8);

	private final OathfallPlugin plugin;
	private final OathfallConfig config;

	public OathfallOverlay(OathfallPlugin plugin, OathfallConfig config)
	{
		this.plugin = plugin;
		this.config = config;

		setPosition(OverlayPosition.TOP_LEFT);
		setLayer(OverlayLayer.ABOVE_WIDGETS);
		panelComponent.setPreferredSize(new Dimension(210, 0));
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		if (!config.showOverlay())
		{
			return null;
		}

		Ledger ledger = plugin.getLedger();
		Vow vow = plugin.activeVow();

		panelComponent.getChildren().clear();
		panelComponent.getChildren().add(TitleComponent.builder()
			.text("Oathfall · Era " + ledger.era.getNumeral())
			.color(EMBER)
			.build());

		panelComponent.getChildren().add(LineComponent.builder()
			.left("Doom")
			.right(ledger.doom + " / 10")
			.rightColor(ledger.doom >= 8 ? DOOM : INK)
			.build());

		panelComponent.getChildren().add(LineComponent.builder()
			.left("Grace")
			.right(ledger.grace + " / " + ledger.graceCap())
			.rightColor(EMBER)
			.build());

		if (!ledger.scars.isEmpty())
		{
			panelComponent.getChildren().add(LineComponent.builder()
				.left("Scars")
				.right(String.valueOf(ledger.scars.size()))
				.rightColor(DOOM)
				.build());
		}

		if (vow == null)
		{
			panelComponent.getChildren().add(LineComponent.builder()
				.left("No Vow sworn")
				.leftColor(DOOM)
				.build());
			return super.render(graphics);
		}

		panelComponent.getChildren().add(LineComponent.builder()
			.left(vow.getObjective())
			.leftColor(INK)
			.build());

		panelComponent.getChildren().add(LineComponent.builder()
			.left(vow.getBinding().getTitle())
			.right(vow.getBinding().isEnforceable() ? "watched" : "honour")
			.leftColor(DOOM)
			.build());

		if (vow.isAutoTracked())
		{
			panelComponent.getChildren().add(LineComponent.builder()
				.left("Progress")
				.right(ledger.activeProgress + " / " + vow.getGoalAmount())
				.rightColor(EMBER)
				.build());
		}

		if (ledger.activeBroken)
		{
			panelComponent.getChildren().add(LineComponent.builder()
				.left("BROKEN")
				.right(ledger.activeBreakReason)
				.leftColor(DOOM)
				.rightColor(DOOM)
				.build());
		}

		if (ledger.heraldDue())
		{
			panelComponent.getChildren().add(LineComponent.builder()
				.left("HERALD")
				.right(ledger.era.getHerald())
				.leftColor(DOOM)
				.rightColor(DOOM)
				.build());
		}

		return super.render(graphics);
	}
}

package com.oathfall.ui;

import com.oathfall.OathfallPlugin;
import com.oathfall.model.Ledger;
import com.oathfall.model.Scar;
import com.oathfall.model.Vow;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.PluginPanel;

import javax.swing.BorderFactory;
import javax.swing.Box;
import javax.swing.BoxLayout;
import javax.swing.JButton;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.SwingUtilities;
import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Component;
import java.awt.Dimension;
import java.awt.GridLayout;

/** The side panel: the ledger up top, the table below, rites at the bottom. */
public class OathfallPanel extends PluginPanel
{
	private static final Color EMBER = new Color(0xC9, 0x94, 0x35);
	private static final Color DOOM = new Color(0xC1, 0x5C, 0x72);
	private static final Color INK_DIM = new Color(0x9A, 0xA0, 0x96);

	private final OathfallPlugin plugin;
	private final JPanel body = new JPanel();

	public OathfallPanel(OathfallPlugin plugin)
	{
		super(false);
		this.plugin = plugin;

		setLayout(new BorderLayout());
		setBorder(BorderFactory.createEmptyBorder(10, 10, 10, 10));
		body.setLayout(new BoxLayout(body, BoxLayout.Y_AXIS));
		add(body, BorderLayout.NORTH);
	}

	public void refresh()
	{
		SwingUtilities.invokeLater(this::rebuild);
	}

	private void rebuild()
	{
		body.removeAll();

		Ledger ledger = plugin.getLedger();

		body.add(title("OATHFALL"));
		body.add(caption("Era " + ledger.era.getNumeral() + " — " + ledger.era.getTitle()
			+ (ledger.hollowed ? " · HOLLOWED" : "")));
		body.add(Box.createVerticalStrut(10));

		body.add(statRow(ledger));
		body.add(Box.createVerticalStrut(12));

		Vow active = plugin.activeVow();
		if (active != null)
		{
			body.add(sectionLabel("THE SWORN VOW"));
			body.add(wrapped(active.getObjective(), Color.WHITE));
			body.add(wrapped(active.getBinding().getTitle() + " — " + active.getBinding().getRule(), DOOM));

			if (active.isAutoTracked())
			{
				body.add(caption("Progress " + ledger.activeProgress + " / " + active.getGoalAmount()));
			}
			else
			{
				body.add(caption("Not machine-trackable. Settle by hand."));
			}

			if (ledger.activeBroken)
			{
				body.add(Box.createVerticalStrut(6));
				body.add(wrapped("BROKEN: " + ledger.activeBreakReason, DOOM));
			}

			body.add(Box.createVerticalStrut(8));
			body.add(button("Settle as Kept", EMBER, e -> plugin.settleKept()));
			body.add(button("Settle as Broken", DOOM,
				e -> plugin.settleBroken(ledger.activeBreakReason == null ? "Settled by hand" : ledger.activeBreakReason)));
		}
		else
		{
			body.add(sectionLabel("THE TABLE"));

			if (plugin.currentHand().isEmpty())
			{
				body.add(caption("No cards dealt."));
			}
			else
			{
				int i = 0;
				for (Vow vow : plugin.currentHand())
				{
					final String id = vow.getId();
					boolean audience = i == 2;
					body.add(Box.createVerticalStrut(6));
					body.add(wrapped((audience ? "[AUDIENCE] " : "") + vow.getId() + " · " + vow.getObjective(), Color.WHITE));
					body.add(wrapped(vow.getBinding().getTitle() + " · " + vow.getLength().getTitle()
						+ " · " + vow.graceValue(audience) + " Grace", INK_DIM));
					body.add(button("Swear this", EMBER, e -> plugin.swear(id)));
					i++;
				}
			}

			body.add(Box.createVerticalStrut(8));
			body.add(button("Deal the Vows", EMBER, e -> plugin.deal()));
		}

		if (ledger.heraldDue())
		{
			body.add(Box.createVerticalStrut(12));
			body.add(sectionLabel("A HERALD STANDS"));
			body.add(wrapped(ledger.era.getHerald() + " — at Doom " + ledger.effectiveDoom()
				+ ". It returns every session until it is answered.", DOOM));
			body.add(button("Herald slain", EMBER, e -> plugin.answerHerald(true)));
			body.add(button("Herald stands", DOOM, e -> plugin.answerHerald(false)));
		}

		if (!ledger.scars.isEmpty())
		{
			body.add(Box.createVerticalStrut(12));
			body.add(sectionLabel("SCARS CARRIED (" + ledger.scars.size() + ")"));
			for (Scar scar : ledger.scars)
			{
				body.add(wrapped("· " + scar.getTitle() + " — " + scar.getRule(), DOOM));
			}
		}

		body.add(Box.createVerticalStrut(12));
		body.add(sectionLabel("THE RELIQUARY"));
		body.add(button("Temper — 2", EMBER, e -> plugin.spend("temper", "")));
		body.add(button("Vigil — 4", EMBER, e -> plugin.spend("vigil", "")));
		body.add(button("Draw a Scar", DOOM, e -> plugin.drawScar()));

		String url = plugin.relayUrl();
		body.add(Box.createVerticalStrut(12));
		body.add(sectionLabel("COMPANION TRACKER"));
		body.add(caption(url == null ? "Relay off — enable it in settings." : url));
		if (url != null)
		{
			body.add(button("Copy tracker link", EMBER, e -> copy(url)));
		}
		body.add(button("Copy ledger JSON", EMBER, e -> copy(plugin.ledgerJson())));

		body.revalidate();
		body.repaint();
	}

	// ------------------------------------------------------------- components

	private JPanel statRow(Ledger ledger)
	{
		JPanel row = new JPanel(new GridLayout(1, 3, 4, 0));
		row.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		row.add(stat("DOOM", String.valueOf(ledger.doom), DOOM));
		row.add(stat("GRACE", ledger.grace + "/" + ledger.graceCap(), EMBER));
		row.add(stat("SCARS", String.valueOf(ledger.scars.size()), INK_DIM));
		row.setMaximumSize(new Dimension(Integer.MAX_VALUE, 46));
		return row;
	}

	private JPanel stat(String label, String value, Color colour)
	{
		JPanel cell = new JPanel(new BorderLayout());
		cell.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		cell.setBorder(BorderFactory.createEmptyBorder(4, 6, 4, 6));

		JLabel l = new JLabel(label);
		l.setFont(FontManager.getRunescapeSmallFont());
		l.setForeground(INK_DIM);

		JLabel v = new JLabel(value);
		v.setFont(FontManager.getRunescapeBoldFont());
		v.setForeground(colour);

		cell.add(l, BorderLayout.NORTH);
		cell.add(v, BorderLayout.CENTER);
		return cell;
	}

	private JLabel title(String text)
	{
		JLabel l = new JLabel(text);
		l.setFont(FontManager.getRunescapeBoldFont());
		l.setForeground(EMBER);
		l.setAlignmentX(Component.LEFT_ALIGNMENT);
		return l;
	}

	private JLabel sectionLabel(String text)
	{
		JLabel l = new JLabel(text);
		l.setFont(FontManager.getRunescapeSmallFont());
		l.setForeground(EMBER);
		l.setAlignmentX(Component.LEFT_ALIGNMENT);
		l.setBorder(BorderFactory.createEmptyBorder(4, 0, 4, 0));
		return l;
	}

	private JLabel caption(String text)
	{
		JLabel l = new JLabel(text);
		l.setFont(FontManager.getRunescapeSmallFont());
		l.setForeground(INK_DIM);
		l.setAlignmentX(Component.LEFT_ALIGNMENT);
		return l;
	}

	/** JLabel has no wrapping, so lean on the HTML renderer for body text. */
	private JLabel wrapped(String text, Color colour)
	{
		JLabel l = new JLabel("<html><body style='width:150px'>" + escape(text) + "</body></html>");
		l.setFont(FontManager.getRunescapeSmallFont());
		l.setForeground(colour);
		l.setAlignmentX(Component.LEFT_ALIGNMENT);
		l.setBorder(BorderFactory.createEmptyBorder(2, 0, 2, 0));
		return l;
	}

	private JButton button(String text, Color colour, java.awt.event.ActionListener action)
	{
		JButton b = new JButton(text);
		b.setFont(FontManager.getRunescapeSmallFont());
		b.setForeground(colour);
		b.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		b.setFocusPainted(false);
		b.setAlignmentX(Component.LEFT_ALIGNMENT);
		b.setMaximumSize(new Dimension(Integer.MAX_VALUE, 26));
		b.addActionListener(action);
		return b;
	}

	private static void copy(String text)
	{
		java.awt.Toolkit.getDefaultToolkit().getSystemClipboard()
			.setContents(new java.awt.datatransfer.StringSelection(text), null);
	}

	private static String escape(String s)
	{
		return s.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;");
	}
}

